/*
 * A192585  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and xy+1 is a prime, then xy+1 is in S, and 2, 5, 8, 11,
 *          and 14 are in S.
 * https://oeis.org/A192585
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 28, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   compare_seq_t, isPrimeGeneric
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A192585:  monotonic closure of {2,5,8,11,14} under x·y+1 prime */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/isPrimeGeneric.h"
#include "../utils/compare_seq_t.h"

static seq_t S[80];      /* enough to hold all 70 terms */
static size_t sz = 0;    /* number of elements actually stored */
static bool initialized = false;

/* simple linear search for presence of a value in S */
static bool contains(seq_t v) {
    for (size_t i = 0; i < sz; ++i) {
        if (S[i] == v) return true;
    }
    return false;
}

/* initialise the sequence once */
static void make_sequence(void) {
    if (initialized) return;
    initialized = true;

    /* initial seeds */
    S[0] = (seq_t)2;
    S[1] = (seq_t)5;
    S[2] = (seq_t)8;
    S[3] = (seq_t)11;
    S[4] = (seq_t)14;
    sz = 5;

    bool changed = true;
    while (changed) {
        changed = false;
        size_t cur_sz = sz;
        for (size_t i = 0; i < cur_sz; ++i) {
            for (size_t j = i; j < cur_sz; ++j) {
                /* using 64‑bit arithmetic: products fit in 64 bits for this problem */
                uint64_t prod = (uint64_t)S[i] * (uint64_t)S[j] + 1ULL;
                seq_t val = (seq_t)prod;
                if (!isPrimeGeneric(val)) continue;
                if (!contains(val)) {
                    S[sz++] = val;
                    changed = true;
                }
            }
        }
    }

    qsort(S, sz, sizeof(seq_t), compare_seq_t);
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for offset below 1 */
    make_sequence();
    if (n <= (idx_t)sz) return S[n - 1];
    return 0;                       /* undefined beyond the finite sequence */
}
